use xiom.io;

fn main() {
  let temperature: Int = 25;
  let is_sunny: Bool = true;

  if temperature > 20 && is_sunny {
    io.println("Wear shorts and a t-shirt!");
  } else {
    io.println("Better wear a jacket.");
  }

  let is_raining: Bool = false;

  if is_raining {
    io.println("Don't forget your umbrella!");
  } else {
    io.println("No rain today � leave the umbrella at home.");
  }
}
